    rows = {r for r in range(h) if all(v == marker for v in grid[r])}
    cols = {c for c in range(w) if all(grid[r][c] == marker for r in range(h))}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r in rows or c in cols:
                out[r][c] = 2
    return out
